1	import { lazy, Suspense } from "react";
2	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
3	import { ThemeProvider } from "next-themes";
4	import { BrowserRouter, Route, Routes } from "react-router-dom";
5	import { Toaster as Sonner } from "@/components/ui/sonner";
6	import { Toaster } from "@/components/ui/toaster";
7	import { TooltipProvider } from "@/components/ui/tooltip";
8	import { AuthProvider } from "@/contexts/AuthContext";
9	import { ProtectedRoute } from "@/components/ProtectedRoute";
10	import { AdminRoute } from "@/components/AdminRoute";
11	import { AppLayout } from "@/components/AppLayout";
12	import Dashboard from "@/pages/Dashboard";
13	import Scan from "@/pages/Scan";
14	import Reports from "@/pages/Reports";
15	import AuditReport from "@/pages/AuditReport";
16	import Integrations from "@/pages/Integrations";
17	import SettingsPage from "@/pages/Settings";
18	import Pricing from "@/pages/Pricing";
19	import Landing from "@/pages/Landing";
20	import Login from "@/pages/Login";
21	import Signup from "@/pages/Signup";
22	import AuthCallback from "@/pages/AuthCallback";
23	import ForgotPassword from "@/pages/ForgotPassword";
24	import ResetPassword from "@/pages/ResetPassword";
25	import Privacy from "@/pages/Privacy";
26	import Terms from "@/pages/Terms";
27	import NotFound from "@/pages/NotFound";
28	import PublicReport from "@/pages/PublicReport";
29	
30	// ── App routes (lazy loaded) ──────────────────────────────────
31	const ScoreHistory = lazy(() => import("@/pages/ScoreHistory"));
32	const Competitors = lazy(() => import("@/pages/Competitors"));
33	
34	// ── Admin routes (lazy loaded) ────────────────────────────────
35	const AdminLayout = lazy(() =>
36	  import("@/components/AdminLayout").then((m) => ({ default: m.AdminLayout }))
37	);
38	const AdminDashboard = lazy(() => import("@/pages/admin/AdminDashboard"));
39	const AdminUsers = lazy(() => import("@/pages/admin/Users"));
40	const AdminUserDetail = lazy(() => import("@/pages/admin/UserDetail"));
41	const AdminAuditLog = lazy(() => import("@/pages/admin/AuditLog"));
42	const AdminScans = lazy(() => import("@/pages/admin/Scans"));
43	const AdminBilling = lazy(() => import("@/pages/admin/Billing"));
44	const AdminSystem = lazy(() => import("@/pages/admin/System"));
45	const AdminFeatureFlags = lazy(() => import("@/pages/admin/FeatureFlags"));
46	const AdminIntegrations = lazy(() => import("@/pages/admin/Integrations"));
47	const AdminSupport = lazy(() => import("@/pages/admin/Support"));
48	
49	function AdminLoadingSpinner() {
50	  return (
51	    <div className="flex min-h-screen items-center justify-center bg-background">
52	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
53	    </div>
54	  );
55	}
56	
57	const queryClient = new QueryClient({
58	  defaultOptions: {
59	    queries: {
60	      staleTime: 1000 * 60 * 2,
61	      gcTime: 1000 * 60 * 10,
62	      retry: (failureCount, error) => {
63	        const msg = error instanceof Error ? error.message : "";
64	        if (msg.includes("401") || msg.includes("403")) return false;
65	        return failureCount < 2;
66	      },
67	      refetchOnWindowFocus: false,
68	    },
69	    mutations: { retry: 0 },
70	  },
71	});
72	
73	const App = () => (
74	  <ThemeProvider attribute="class" defaultTheme="light" enableSystem={false}>
75	    <QueryClientProvider client={queryClient}>
76	      <TooltipProvider>
77	        <Toaster />
78	        <Sonner />
79	      <BrowserRouter>
80	        <AuthProvider>
81	          <Routes>
82	            {/* Public routes */}
83	            <Route path="/" element={<Landing />} />
84	            <Route path="/login" element={<Login />} />
85	            <Route path="/signup" element={<Signup />} />
86	            <Route path="/auth/callback" element={<AuthCallback />} />
87	            <Route path="/forgot-password" element={<ForgotPassword />} />
88	            <Route path="/reset-password" element={<ResetPassword />} />
89	            <Route path="/pricing" element={<Pricing />} />
90	            <Route path="/privacy" element={<Privacy />} />
91	            <Route path="/terms" element={<Terms />} />
92	            <Route path="/r/:token" element={<PublicReport />} />
93	
94	            {/* Protected app routes */}
95	            <Route element={<ProtectedRoute />}>
96	              <Route element={<AppLayout />}>
97	                <Route path="/dashboard" element={<Dashboard />} />
98	                <Route path="/scan" element={<Scan />} />
99	                <Route path="/reports" element={<Reports />} />
100	                <Route path="/reports/:id" element={<AuditReport />} />
101	                <Route
102	                  path="/history"
103	                  element={
104	                    <Suspense fallback={<AdminLoadingSpinner />}>
105	                      <ScoreHistory />
106	                    </Suspense>
107	                  }
108	                />
109	                <Route path="/integrations" element={<Integrations />} />
110	                <Route path="/settings" element={<SettingsPage />} />
111	                <Route
112	                  path="/competitors"
113	                  element={
114	                    <Suspense fallback={<AdminLoadingSpinner />}>
115	                      <Competitors />
116	                    </Suspense>
117	                  }
118	                />
119	              </Route>
120	
121	              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
122	              <Route element={<AdminRoute />}>
123	                <Route
124	                  path="/admin"
125	                  element={
126	                    <Suspense fallback={<AdminLoadingSpinner />}>
127	                      <AdminLayout />
128	                    </Suspense>
129	                  }
130	                >
131	                  <Route
132	                    index
133	                    element={
134	                      <Suspense fallback={<AdminLoadingSpinner />}>
135	                        <AdminDashboard />
136	                      </Suspense>
137	                    }
138	                  />
139	                  <Route
140	                    path="users"
141	                    element={
142	                      <Suspense fallback={<AdminLoadingSpinner />}>
143	                        <AdminUsers />
144	                      </Suspense>
145	                    }
146	                  />
147	                  <Route
148	                    path="users/:userId"
149	                    element={
150	                      <Suspense fallback={<AdminLoadingSpinner />}>
151	                        <AdminUserDetail />
152	                      </Suspense>
153	                    }
154	                  />
155	                  <Route
156	                    path="audit-log"
157	                    element={
158	                      <Suspense fallback={<AdminLoadingSpinner />}>
159	                        <AdminAuditLog />
160	                      </Suspense>
161	                    }
162	                  />
163	                  <Route
164	                    path="scans"
165	                    element={
166	                      <Suspense fallback={<AdminLoadingSpinner />}>
167	                        <AdminScans />
168	                      </Suspense>
169	                    }
170	                  />
171	                  <Route
172	                    path="billing"
173	                    element={
174	                      <Suspense fallback={<AdminLoadingSpinner />}>
175	                        <AdminBilling />
176	                      </Suspense>
177	                    }
178	                  />
179	                  <Route
180	                    path="system"
181	                    element={
182	                      <Suspense fallback={<AdminLoadingSpinner />}>
183	                        <AdminSystem />
184	                      </Suspense>
185	                    }
186	                  />
187	                  <Route
188	                    path="flags"
189	                    element={
190	                      <Suspense fallback={<AdminLoadingSpinner />}>
191	                        <AdminFeatureFlags />
192	                      </Suspense>
193	                    }
194	                  />
195	                  <Route
196	                    path="integrations"
197	                    element={
198	                      <Suspense fallback={<AdminLoadingSpinner />}>
199	                        <AdminIntegrations />
200	                      </Suspense>
201	                    }
202	                  />
203	                  <Route
204	                    path="support"
205	                    element={
206	                      <Suspense fallback={<AdminLoadingSpinner />}>
207	                        <AdminSupport />
208	                      </Suspense>
209	                    }
210	                  />
211	                </Route>
212	              </Route>
213	            </Route>
214	
215	            <Route path="*" element={<NotFound />} />
216	          </Routes>
217	        </AuthProvider>
218	      </BrowserRouter>
219	      </TooltipProvider>
220	    </QueryClientProvider>
221	  </ThemeProvider>
222	);
223	
224	export default App;
