23	interface NavItem {
24	  title: string;
25	  url: string;
26	  icon: React.ElementType;
27	  flagKey?: string;
28	}
29	
30	const BASE_NAV_ITEMS: NavItem[] = [
31	  { title: "Dashboard", url: "/dashboard", icon: LayoutDashboard },
32	  { title: "New Scan", url: "/scan", icon: ScanLine },
33	  { title: "My Reports", url: "/reports", icon: FileText },
34	  { title: "Score History", url: "/history", icon: TrendingUp },
35	  { title: "Competitors", url: "/competitors", icon: Swords },
36	  { title: "Integrations", url: "/integrations", icon: Puzzle, flagKey: "integrations_enabled" },
37	  { title: "Settings", url: "/settings", icon: Settings },
38	];
39	
40	export function AppSidebar() {
41	  const { state } = useSidebar();
42	  const collapsed = state === "collapsed";
43	  const location = useLocation();
44	  const { profile } = useAuth();
45	
46	  const integrationsEnabled = useFeatureFlag("integrations_enabled", true);
47	
48	  const navItems = BASE_NAV_ITEMS.filter((item) => {
49	    if (item.flagKey === "integrations_enabled") return integrationsEnabled;
50	    return true;
51	  });
52	
53	  const scansUsed = profile?.scans_used ?? 0;
54	  const scanLimit = profile?.scan_limit ?? 3;
55	  const usagePercent = Math.round((scansUsed / scanLimit) * 100);
56	
57	  const isActive = (path: string) =>
58	    location.pathname === path || location.pathname.startsWith(path + "/");
59	
60	  return (
61	    <Sidebar collapsible="icon" className="border-r-0">
62	      <SidebarHeader className="px-4 py-5 group-data-[collapsible=icon]:px-2 group-data-[collapsible=icon]:py-4 group-data-[collapsible=icon]:items-center">
63	        <Link to="/dashboard" className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-full">
64	          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-sidebar-primary shrink-0">
65	            <ScanLine className="h-3.5 w-3.5 text-white" />
66	          </div>
67	          {!collapsed && (
68	            <span className="text-base font-semibold tracking-tight text-white">
69	              ConvertScan
70	            </span>
71	          )}
72	        </Link>
73	      </SidebarHeader>
74	
75	      <SidebarContent className="px-2 group-data-[collapsible=icon]:px-1">
76	        <SidebarGroup>
77	          <SidebarGroupContent>
78	            <SidebarMenu className="space-y-0.5">
79	              {navItems.map((item) => {
80	                const active = isActive(item.url);
81	                return (
82	                  <SidebarMenuItem key={item.title}>
83	                    <SidebarMenuButton
84	                      asChild
85	                      tooltip={item.title}
86	                      isActive={active}
87	                      className={cn(
88	                        "h-10 transition-colors duration-150 relative",
89	                        active
90	                          ? "bg-white/10 text-white before:absolute before:left-0 before:top-2 before:bottom-2 before:w-[2px] before:rounded-full before:bg-primary"
91	                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white/80"
92	                      )}
93	                    >
94	                      <NavLink to={item.url} activeClassName="">
95	                        <item.icon className={cn(
96	                          "h-[18px] w-[18px] shrink-0",
97	                          active ? "text-white" : "text-white/55"
98	                        )} />
99	                        <span className="text-sm font-medium">{item.title}</span>
100	                      </NavLink>
101	                    </SidebarMenuButton>
102	                  </SidebarMenuItem>
103	                );
104	              })}
105	            </SidebarMenu>
106	          </SidebarGroupContent>
107	        </SidebarGroup>
108	      </SidebarContent>
109	
110	      <SidebarFooter className="p-3 group-data-[collapsible=icon]:p-2 group-data-[collapsible=icon]:items-center">
111	        {/* Scan usage indicator — expanded only */}
112	        {!collapsed && (
113	          <div className="mb-3 rounded-lg bg-white/5 p-3">
114	            <div className="flex items-center justify-between mb-1.5">
115	              <span className="text-xs text-white/40">Scans used</span>
116	              <span className="text-xs font-medium text-white/70 tabular-nums">
117	                {profile ? `${scansUsed}/${scanLimit}` : "\u2014"}
118	              </span>
119	            </div>
120	            <Progress value={profile ? usagePercent : 0} className="h-1" />
121	            <div className="mt-1.5">
122	              <Badge
123	                variant="outline"
124	                className="border-white/10 bg-transparent text-2xs text-white/40 capitalize px-1.5 py-0"
125	              >
126	                {profile?.plan ?? "free"} plan
127	              </Badge>
128	            </div>
129	          </div>
130	        )}
131	
132	        {/* Separator — hidden when collapsed (nothing above it) */}
133	        {!collapsed && <Separator className="mb-3 bg-white/5" />}
134	
135	        {profile?.plan !== "agency" && profile?.plan !== "pro" && (
136	          !collapsed ? (
137	            <Link
138	              to="/pricing"
139	              className="flex items-center justify-center gap-2 rounded-lg bg-sidebar-primary px-4 py-2.5 text-sm font-semibold text-white transition-all hover:opacity-90 hover:shadow-lg hover:shadow-sidebar-primary/20"
140	            >
141	              <Zap className="h-4 w-4" />
142	              Upgrade Plan
143	            </Link>
144	          ) : (
145	            <Link
146	              to="/pricing"
147	              aria-label="Upgrade Plan"
148	              className="flex h-9 w-9 items-center justify-center rounded-lg bg-sidebar-primary text-white transition-opacity hover:opacity-90"
149	            >
150	              <Zap className="h-4 w-4" />
151	            </Link>
152	          )
153	        )}
154	      </SidebarFooter>
155	    </Sidebar>
156	  );
157	}
