1	import { type LucideIcon } from "lucide-react";
2	
3	// ── User / Auth ──────────────────────────────────────────────
4	
5	export type UserRole = "user" | "admin" | "super_admin";
6	
7	export interface UserProfile {
8	  id: string;
9	  email: string;
10	  full_name: string;
11	  company_name: string | null;
12	  website_url: string | null;
13	  avatar_url: string | null;
14	  plan: PlanType;
15	  scans_used: number;
16	  scan_limit: number;
17	  role: UserRole;
18	  is_banned: boolean;
19	  created_at: string;
20	  billing_cycle_end: string;
21	}
22	
23	export type PlanType = "free" | "starter" | "growth" | "pro" | "agency";
24	
25	// ── Plan Helpers ────────────────────────────────────────────
26	
27	/** Any paid plan (starter and above) */
28	export function isPaidPlan(plan: PlanType): boolean {
29	  return plan !== "free";
30	}
31	
32	/** Growth plan and above (growth, pro, agency) */
33	export function isGrowthPlus(plan: PlanType): boolean {
34	  return plan === "growth" || plan === "pro" || plan === "agency";
35	}
36	
37	/** Pro plan and above (pro, agency) */
38	export function isProPlus(plan: PlanType): boolean {
39	  return plan === "pro" || plan === "agency";
40	}
41	
42	/** Agency plan only */
43	export function isAgencyPlan(plan: PlanType): boolean {
44	  return plan === "agency";
45	}
46	
47	// ── Scans ────────────────────────────────────────────────────
48	
49	export type ScanStatus = "pending" | "analyzing" | "completed" | "failed";
50	
51	export type PageType =
52	  | "landing"
53	  | "product"
54	  | "homepage"
55	  | "pricing"
56	  | "signup"
57	  | "blog"
58	  | "other";
59	
60	export interface Scan {
61	  id: string;
62	  user_id: string;
63	  url: string;
64	  favicon_url: string | null;
65	  page_title: string | null;
66	  page_type: PageType;
67	  status: ScanStatus;
68	  overall_score: number | null;
69	  issues_found: number;
70	  critical_issues: number;
71	  warnings: number;
72	  quick_wins: number;
73	  screenshot_url: string | null;
74	  device: "desktop" | "mobile" | "both";
75	  share_token: string | null;
76	  is_public: boolean;
77	  created_at: string;
78	  completed_at: string | null;
79	}
80	
81	export type IndustryType = "saas" | "ecommerce" | "agency" | "finance" | "healthcare";
82	
83	export interface IndustryBenchmark {
84	  id: string;
85	  industry: string;
86	  page_type: string;
87	  pillar: string;
88	  avg_score: number;
89	  sample_size: number;
90	  updated_at: string;
91	}
92	
93	// ── CRO Pillars ──────────────────────────────────────────────
94	
95	export type CroPillar =
96	  | "value_proposition"
97	  | "cta_effectiveness"
98	  | "trust_signals"
99	  | "visual_hierarchy"
100	  | "mobile_experience"
101	  | "content_copy"
102	  | "page_performance";
103	
104	export type Severity = "critical" | "warning" | "info" | "passed";
105	export type Effort = "quick" | "moderate" | "significant";
106	
107	export interface Finding {
108	  id: string;
109	  title: string;
110	  severity: Severity;
111	  current_state: string;
112	  recommendation: string;
113	  ai_suggestion: string;
114	  is_premium: boolean;
115	  effort: Effort;
116	  estimated_lift: string; // e.g. "1-3% conversion lift"
117	  category: string; // e.g. "Copy", "Design", "Technical"
118	}
119	
120	export interface PillarResult {
121	  id: string;
122	  scan_id: string;
123	  pillar: CroPillar;
124	  score: number;
125	  weight: number; // pillar weight in overall score (0-1)
126	  benchmark: number; // industry average for this pillar
127	  findings: Finding[];
128	}
129	
130	export type CopyRewriteElementType =
131	  | "headline"
132	  | "subheadline"
133	  | "cta"
