286	    }
287	
288	    // ── 10b. Copy Rewrites (Growth+ only, non-fatal) ───────────
289	    try {
290	      const { data: userProfile } = await supabase
291	        .from("profiles")
292	        .select("plan")
293	        .eq("id", user.id)
294	        .single();
295	
296	      const isGrowthPlus = userProfile?.plan === "growth" ||
297	        userProfile?.plan === "pro" ||
