409	        user_id: user.id,
410	        url_hash: urlHash,
411	        url,
412	        scan_id: scanId,
413	        score: scoring.overall_score,
414	        pillar_scores: pillarScores,
415	        scanned_at: new Date().toISOString(),
416	      });
417	    } catch (historyErr) {
418	      // Non-fatal — never fail a scan because of history insert
419	      console.warn("scan_history insert failed (non-fatal):", historyErr);
420	    }
421	
422	    // Update scan to completed
423	    const { error: updateError } = await supabase
424	      .from("scans")
425	      .update({
426	        status: "completed",
427	        overall_score: scoring.overall_score,
428	        issues_found: scoring.issues_found,
429	        critical_issues: scoring.critical_issues,
430	        warnings: scoring.warnings,
431	        quick_wins: scoring.quick_wins,
432	        completed_at: new Date().toISOString(),
433	      })
434	      .eq("id", scanId);
435	
436	    if (updateError) {
437	      console.error("Failed to update scan status:", updateError);
438	      // Results are saved — don't fail the whole scan
439	    }
440	
441	    // ── 11. Send scan complete email (fire-and-forget) ─────────────
442	    try {
443	      // Fetch user profile for name and email
444	      const [profileRes, emailRes] = await Promise.all([
445	        supabase
446	          .from("profiles")
447	          .select("full_name, company_name")
448	          .eq("id", user.id)
449	          .single(),
450	        supabase.auth.admin.getUserById(user.id),
451	      ]);
452	
453	      const userName = profileRes.data?.full_name ?? "there";
454	      const userEmail = emailRes.data?.user?.email;
455	
456	      if (userEmail) {
457	        await supabase.functions.invoke("send-email", {
458	          body: {
459	            type: "scan_complete",
460	            to: userEmail,
461	            data: {
462	              name: userName,
463	              url,
464	              score: scoring.overall_score,
465	              scan_id: scanId,
466	              critical_count: scoring.critical_issues,
467	              quick_wins: scoring.quick_wins,
468	            },
469	          },
470	        });
471	      }
472	    } catch (emailErr) {
473	      // Non-critical: never fail a scan because the notification email failed
474	      console.warn("Scan complete email failed (non-fatal):", emailErr);
475	    }
476	
477	    return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
478	  } catch (error) {
479	    const msg = error instanceof Error ? error.message : "Unexpected error during scan";
480	    console.error("Unexpected scan error:", error);
481	    await failScan(msg);
482	    return corsResponse({ error: "Scan failed due to an unexpected error" }, 500);
483	  }
