586	function parseHtml(
587	  html: string,
588	  baseUrl: string,
589	): { domData: DomData; pageTitle: string; faviconUrl: string } {
590	  // Extract title
591	  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
592	  const pageTitle = titleMatch ? decodeHtmlEntities(titleMatch[1].trim()) : "";
593	
594	  // Extract favicon
595	  const faviconMatch = html.match(
596	    /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
597	  ) ?? html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'](?:shortcut )?icon["']/i);
598	  let faviconUrl = "";
599	  if (faviconMatch) {
600	    try {
601	      faviconUrl = new URL(faviconMatch[1], baseUrl).toString();
602	    } catch (_) {
603	      faviconUrl = faviconMatch[1];
604	    }
605	  }
606	
607	  // Extract meta description
608	  const metaMatch = html.match(
609	    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
610	  ) ?? html.match(
611	    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i,
612	  );
613	  const metaDescription = metaMatch ? decodeHtmlEntities(metaMatch[1]) : "";
614	
615	  // Extract headings h1-h4
616	  const headings: string[] = [];
617	  const headingRegex = /<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
618	  let hMatch;
619	  while ((hMatch = headingRegex.exec(html)) !== null && headings.length < 20) {
620	    const text = stripTags(hMatch[2]).trim();
621	    if (text) headings.push(text);
622	  }
623	
624	  // Extract buttons and links with CTA-like text
625	  const ctaButtons: string[] = [];
626	  const ctaKeywords = /\b(get|start|try|sign|join|buy|shop|order|book|schedule|download|learn|see|watch|explore|discover|request|contact|subscribe)\b/i;
627	  const buttonRegex = /<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi;
628	  let btnMatch;
629	  while ((btnMatch = buttonRegex.exec(html)) !== null && ctaButtons.length < 15) {
630	    const text = stripTags(btnMatch[1]).trim();
631	    if (text && text.length < 60 && ctaKeywords.test(text)) {
632	      ctaButtons.push(text);
633	    }
634	  }
635	
636	  // Extract images
637	  const images: Array<{ src: string; alt: string }> = [];
638	  const imgRegex = /<img[^>]+>/gi;
639	  let imgMatch;
640	  while ((imgMatch = imgRegex.exec(html)) !== null && images.length < 20) {
641	    const srcMatch = imgMatch[0].match(/src=["']([^"']+)["']/i);
642	    const altMatch = imgMatch[0].match(/alt=["']([^"']*)["']/i);
643	    if (srcMatch) {
644	      images.push({
645	        src: srcMatch[1],
646	        alt: altMatch ? altMatch[1] : "",
647	      });
648	    }
649	  }
650	
651	  // Extract links
652	  const links: Array<{ text: string; href: string }> = [];
653	  const linkRegex = /<a[^>]+href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
654	  let linkMatch;
655	  while ((linkMatch = linkRegex.exec(html)) !== null && links.length < 30) {
656	    const text = stripTags(linkMatch[2]).trim();
657	    if (text && text.length < 80) {
658	      links.push({ text, href: linkMatch[1] });
659	    }
660	  }
661	
662	  // Count forms
663	  const forms = (html.match(/<form[^>]*>/gi) ?? []).length;
664	
665	  // Heuristic: extract testimonial-like text blocks (blockquote or q tags)
666	  const testimonials: string[] = [];
667	  const quoteRegex = /<(?:blockquote|q)[^>]*>([\s\S]*?)<\/(?:blockquote|q)>/gi;
668	  let qMatch;
669	  while ((qMatch = quoteRegex.exec(html)) !== null && testimonials.length < 5) {
670	    const text = stripTags(qMatch[1]).trim();
671	    if (text && text.length > 30) testimonials.push(text.slice(0, 300));
672	  }
673	
674	  // Extract body text (strip scripts, styles, nav, footer first)
675	  let bodyText = html
676	    .replace(/<script[\s\S]*?<\/script>/gi, "")
677	    .replace(/<style[\s\S]*?<\/style>/gi, "")
678	    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
679	    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
680	    .replace(/<header[\s\S]*?<\/header>/gi, "");
681	  bodyText = stripTags(bodyText).replace(/\s+/g, " ").trim();
682	
683	  // Detect trust badges from common keywords
684	  const trustBadges: string[] = [];
685	  const badgeKeywords = [
686	    "SSL", "GDPR", "SOC 2", "ISO", "PCI", "HIPAA", "BBB",
687	    "Trustpilot", "G2", "Capterra", "Product Hunt", "4.8", "4.9", "5.0",
688	    "money-back guarantee", "100% satisfaction", "secure checkout",
689	    "verified", "certified", "award",
690	  ];
691	  for (const kw of badgeKeywords) {
692	    if (html.toLowerCase().includes(kw.toLowerCase())) {
693	      trustBadges.push(kw);
694	    }
695	  }
696	
697	  return {
698	    domData: {
699	      headings,
700	      cta_buttons: ctaButtons,
701	      images,
702	      meta_description: metaDescription,
703	      body_text: bodyText,
704	      links,
705	      forms,
706	      testimonials,
707	      trust_badges: trustBadges,
708	    },
709	    pageTitle,
710	    faviconUrl,
711	  };
712	}
