715	
716	async function uploadScreenshot(
717	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
718	  supabase: Record<string, any>,
719	  base64Data: string,
720	  scanId: string,
721	): Promise<string> {
722	  // Decode base64 to Uint8Array
723	  const binaryStr = atob(base64Data);
724	  const bytes = new Uint8Array(binaryStr.length);
725	  for (let i = 0; i < binaryStr.length; i++) {
726	    bytes[i] = binaryStr.charCodeAt(i);
727	  }
728	
729	  const path = `${scanId}/screenshot.jpg`;
730	  const { error } = await supabase.storage
731	    .from("screenshots")
732	    .upload(path, bytes, {
733	      contentType: "image/jpeg",
734	      upsert: true,
735	    });
736	
737	  if (error) throw new Error(`Storage upload failed: ${error.message}`);
738	
739	  const { data } = supabase.storage.from("screenshots").getPublicUrl(path);
740	  return data.publicUrl;
741	}
