export function useCreateScan() {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ url, page_type }: CreateScanInput): Promise<Scan> => {
      const { data: scanData } = await supabase.from("scans").insert({...}).select().single();
      const scan = rowToScan(scanData);

      supabase.functions.invoke("analyze-url", {
        body: { scan_id: scan.id, url, page_type }
      }).catch(err => toast.error(...));

      return scan;
    },
    onSuccess: (data) => {
      queryClient.setQueryData(scanKeys.list(user.id), prev => [data, ...prev]);
