### **13. KEY PATTERNS TO REUSE**

**useQuery + useMutation Pattern:**
```typescript
export const scanKeys = {
  all: ["scans"] as const,
  lists: () => [...scanKeys.all, "list"] as const,
  list: (userId: string) => [...scanKeys.lists(), userId] as const,
  details: () => [...scanKeys.all, "detail"] as const,
  detail: (id: string) => [...scanKeys.details(), id] as const,
};

export function useScan(id: string | undefined) {
  return useQuery({
    queryKey: scanKeys.detail(id ?? ""),
    queryFn: async () => { /* supabase call */ },
    enabled: !!id && !!user?.id,
    staleTime: 0,
  });
}
```

**Billing Hook Pattern (reuse for API subscriptions):**
```typescript
export function useCheckout() {
  return useMutation({
    mutationFn: async (params) => {
      const { data, error } = await supabase.functions.invoke("dodo-checkout", {
        body: params,
      });
      if (error) throw new Error(error.message);
      if (!data?.url) throw new Error("No URL returned");
      return data.url;
    },
    onSuccess: (url) => { window.location.href = url; },
    onError: (error) => { toast.error(message); },
  });
}
```

**Plan Gating Pattern:**
```typescript
import { isPaidPlan, isGrowthPlus, isProPlus, isAgencyPlan } from "@/types";

if (!isProPlus(profile.plan)) {
  return <PremiumLock tier="Pro" feature="Bulk Scanning" />;
}
```

**Integrations Hook Pattern:**
```typescript
export type IntegrationProvider = "hotjar" | "google_analytics" | "clarity";

export function useIntegrations() {
  return useQuery({
    queryKey: ["integrations", user?.id],
    queryFn: async () => {
      const { data } = await supabase
        .from("integrations")
        .select("*")
        .eq("user_id", user.id);
      return data || [];
    },
  });
}

export function useConnectIntegration() {
  return useMutation({
    mutationFn: async ({ provider, accessToken }: ConnectInput) => {
      return supabase.from("integrations").insert({
        user_id: user.id,
        provider,
        access_token: accessToken,
      });
    },
  });
}
```

